('7a676eca-3633-4ad9-a70a-7d455eb390e3', 'Su hào', 'g', 'RAU_CU', 37, 2.8, 0.1, 6.2, TRUE, 'Tham chiếu VN FCT: Su hào', NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('90bb305b-2dbc-437c-9e48-49f88a60c439', 'Su su', 'g', 'RAU_CU', 19, 0.8, 0.1, 3.6, TRUE, 'Tham chiếu VN FCT: Su su', NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('b5e72b51-3567-4ff8-b27a-12e92efec6bc', 'Thịt heo ba chỉ', 'g', 'THIT_DO', 260, 16.5, 21.5, 0, TRUE, 'Tham chiếu VN FCT: Thịt heo ba chỉ', NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('1c1c3329-629a-485f-8f0b-ab3c966a66bb', 'Thịt vịt', 'g', 'GIA_CAM', 267, 17.8, 21.8, 0, TRUE, 'Tham chiếu VN FCT: Thịt vịt', NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
