('c99102ac-9db1-4535-8a38-240adad5a313', 'Đu đủ chín', 'g', 'RAU_CU', 36, 1, 0.1, 7.6, TRUE, 'Tham chiếu VN FCT: Đu đủ chín', NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
