INSERT INTO dishes (id, name, slot_code, food_group_code,
    kcal_per_100g, protein_per_100g, fat_per_100g, carb_per_100g,
    base_serving_g, unit, description, is_active,
    created_at, updated_at, created_by, updated_by) VALUES
('28cc58b1-0675-45eb-b663-0adb726c93b0', 'Gà luộc', 'CHINH', 'GIA_CAM', 215, 24, 13, 0, 100, 'đĩa nhỏ', 'Gà ta luộc nguyên con rồi chặt miếng. Số liệu tính phần có da.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('a74239bc-3d28-450f-9936-147916897036', 'Gà kho gừng', 'CHINH', 'GIA_CAM', 200, 19, 11, 4, 120, 'đĩa nhỏ', 'Đùi/má đùi gà kho với gừng, nước mắm, đường, dầu ăn.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('a143d311-41ff-4ae2-97e8-46f1dd948300', 'Gà rang muối', 'CHINH', 'GIA_CAM', 260, 22, 18, 3, 120, 'đĩa nhỏ', 'Gà chiên ngập dầu rồi rang với muối, sả băm, lá chanh.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('26f2fc12-bb6c-4d89-b986-cbe25d9eddb8', 'Cánh gà chiên nước mắm', 'CHINH', 'GIA_CAM', 290, 21, 19, 7, 120, 'đĩa nhỏ', 'Cánh gà chiên giòn áo sốt nước mắm đường tỏi.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('cc2d54ee-d271-454f-8332-ff9d6821a020', 'Gà xào sả ớt', 'CHINH', 'GIA_CAM', 220, 20, 14, 3, 120, 'đĩa nhỏ', 'Thịt gà cắt miếng xào với sả băm, ớt, hành tây.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('7bf43cac-8bf0-4030-a56a-af986ede4c74', 'Gà nướng mật ong', 'CHINH', 'GIA_CAM', 215, 22, 11, 7, 130, 'đĩa nhỏ', 'Đùi/má đùi gà ướp mật ong, nước tương, tỏi rồi nướng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('7be013be-4059-4a69-bc06-c375afdad8e6', 'Gà hấp lá chanh', 'CHINH', 'GIA_CAM', 210, 24, 12, 1, 120, 'đĩa nhỏ', 'Gà ta hấp với lá chanh, gừng, sả. Giữ nguyên vị tự nhiên.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('97db7601-d97e-42bf-8f1a-c68f04c7191e', 'Gà hầm thuốc bắc', 'CHINH', 'GIA_CAM', 180, 16, 9, 7, 150, 'bát', 'Gà hầm với hạt sen, táo đỏ, kỷ tử, đảng sâm. base_serving không tính nước canh dư.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d2dfb26f-6ec8-4903-8560-e986dd5fe7f3', 'Vịt kho gừng', 'CHINH', 'GIA_CAM', 265, 18, 19, 4, 120, 'đĩa nhỏ', 'Vịt có da kho với nhiều gừng, nước mắm, đường để khử mùi.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('a908a9d7-205d-4b0e-bba9-64fc4a58aed0', 'Vịt om sấu', 'CHINH', 'GIA_CAM', 215, 16, 14, 7, 150, 'bát', 'Vịt om với sấu, khoai sọ, gừng. base_serving không tính nước om dư.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8a72ad82-380d-41fb-8b26-9c05a6a96081', 'Thịt kho tàu', 'CHINH', 'THIT_DO', 270, 15.5, 20, 5, 130, 'đĩa nhỏ', 'Ba chỉ heo kho cùng trứng và nước dừa tươi, kiểu Nam Bộ vị ngọt. Bao gồm nước sốt sệt khi tính kcal/100g.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d53b01b8-a670-4940-864a-3d55fa5189ee', 'Thịt kho tiêu', 'CHINH', 'THIT_DO', 235, 20, 14, 4, 100, 'đĩa nhỏ', 'Kho khô kiểu Bắc, dùng nạc vai heo, vị mặn đậm và nhiều tiêu xay. Nước sốt rất ít, gần như cô cạn.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('0a5e111f-860c-408c-9b0b-90adacdfbc81', 'Thịt rang cháy cạnh', 'CHINH', 'THIT_DO', 320, 18, 25, 5, 100, 'đĩa nhỏ', 'Ba chỉ thái mỏng rang khô đến cạnh xém vàng, không thêm dầu vì thịt tự ra mỡ. Vị mặn ngọt.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('a85b38f7-1d26-4024-9482-ca95eb27204f', 'Thịt luộc', 'CHINH', 'THIT_DO', 290, 20, 23, 0.5, 120, 'đĩa nhỏ', 'Ba chỉ heo luộc, không tính nước chấm (mắm tôm/mắm chanh ớt) trong macro vì lượng dùng nhỏ.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('525db032-c29f-4ce3-9cba-e0b1b0510572', 'Thịt bò xào hành tây', 'CHINH', 'THIT_DO', 155, 16, 8, 5, 130, 'đĩa nhỏ', 'Bò thăn thái mỏng xào nhanh lửa to với hành tây. Carb chủ yếu từ hành tây.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('9b800a75-9a5c-4ea6-862a-59eb44f42e59', 'Bò xào cần tỏi', 'CHINH', 'THIT_DO', 150, 17, 8, 3, 130, 'đĩa nhỏ', 'Bò thăn xào với cần tây và tỏi, ít dầu. Carb thấp hơn bò xào hành tây.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d8c7f0cb-6500-4666-bf50-d15ce19206e7', 'Bò kho', 'CHINH', 'THIT_DO', 175, 12, 10, 7, 200, 'đĩa nhỏ', 'Bò nạm hầm cà rốt với ngũ vị hương và sả, có nước sốt. Tính kcal/100g cho cả phần thịt + cà rốt + nước sốt nên thấp hơn các món kho khô. Ăn kèm cơm theo note.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('0ee276e0-16aa-44dc-bd83-164aef376cca', 'Sườn xào chua ngọt', 'CHINH', 'THIT_DO', 260, 15, 15, 13, 130, 'đĩa nhỏ', 'Sườn non chiên rồi đảo với sốt cà chua, giấm, đường. Carb cao do đường trong nước sốt. Khối lượng đã trừ xương, không tính phần xương.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('5e481b61-39f0-46b4-b916-c6436f409c11', 'Sườn rim mặn', 'CHINH', 'THIT_DO', 270, 17, 17, 8, 130, 'đĩa nhỏ', 'Sườn non rim nước mắm đường đến nước sốt sệt. Khối lượng đã trừ xương, không tính phần xương.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('c2216286-2247-46bf-b04b-1b05b0d1978b', 'Sườn nướng', 'CHINH', 'THIT_DO', 250, 20, 14, 7, 130, 'miếng', 'Sườn cốt lết ướp sả, mật ong, nước mắm rồi nướng. Ít mỡ hơn sườn non. Khối lượng đã trừ xương.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('abe40486-2438-4627-be76-86da266aa352', 'Chả lá lốt', 'CHINH', 'THIT_DO', 215, 15, 14, 4, 100, 'đĩa nhỏ', 'Thịt nạc vai heo băm cuốn lá lốt rồi rán/nướng. Dùng nạc vai (~12-15% fat) để đủ kết dính, không dùng ba chỉ.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('09c09f00-6ac5-468a-8b4f-0887c9378943', 'Bò hầm khoai tây cà rốt', 'CHINH', 'THIT_DO', 165, 11, 8, 11, 200, 'đĩa nhỏ', 'Bò nạm hầm với khoai tây và cà rốt, vị nhạt hơn bò kho. Carb cao hơn bò kho do khoai tây. Tính kcal/100g cho cả phần thịt + rau củ + nước.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('9add6ea5-d522-4cad-9034-114287cca72b', 'Cá kho tộ', 'CHINH', 'CA', 195, 15, 12.5, 4.5, 120, 'đĩa nhỏ', 'Cá basa kho nồi đất với nước hàng caramel, nước mắm, tiêu. Kiểu Nam, nước kho sánh ngọt. base_serving gồm cả phần nước kho.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('1cdc80bb-29c8-4680-9ccf-59db89b94b96', 'Cá kho riềng', 'CHINH', 'CA', 165, 17, 8, 4, 120, 'đĩa nhỏ', 'Cá trắm kho với riềng, nghệ tươi, nước mắm. Kiểu Bắc, ít đường hơn kho tộ. Cá nạc nên fat thấp hơn.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('be3710b5-0893-4b47-8a38-b6d72f7cc8ec', 'Cá kho tiêu', 'CHINH', 'CA', 175, 19, 9, 3, 100, 'đĩa nhỏ', 'Cá rô đồng kho khô cạn với tiêu xay và tiêu nguyên hạt, nước mắm. Đậm đà, ít nước. base_serving nhỏ vì kho cạn.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('4e46c439-6fb4-49d8-a57c-fc58288b8a9f', 'Cá rán', 'CHINH', 'CA', 215, 22, 13, 1, 120, 'khúc', 'Cá rô phi rán nguyên khúc, KHÔNG tẩm bột. Carb thấp do không có bột áo. Chấm mắm gừng (không tính trong base_serving).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e55135b4-0731-4f49-a295-f3c1a4077eb5', 'Cá chiên xù', 'CHINH', 'CA', 250, 18, 15, 12, 130, 'phần', 'Cá basa phi lê tẩm bột chiên xù, chiên ngập dầu. Carb cao do bột áo, fat cao do hút dầu. Phi lê = 100% ăn được.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('b3861d5e-aa4a-4962-b902-9f0cd1869896', 'Cá hấp xì dầu', 'CHINH', 'CA', 135, 19, 5, 2, 130, 'phần', 'Cá rô phi hấp với gừng, hành lá, rưới xì dầu nóng + dầu ăn nhỏ giọt. Không thêm dầu trong quá trình nấu. base_serving = phần ăn được của cá nguyên con.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('ab8eecb8-b424-4fcf-9623-a384c9fb8c16', 'Cá hấp gừng', 'CHINH', 'CA', 130, 18, 5, 2, 130, 'phần', 'Cá chép hấp cách thủy với nhiều gừng tươi thái sợi. Tương tự hấp xì dầu nhưng vị gừng nổi trội. Phần ăn được.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8c8bd6ee-b2ef-49d4-8301-96275ec08fae', 'Cá nướng giấy bạc', 'CHINH', 'CA', 160, 21, 7, 2, 130, 'phần', 'Cá diêu hồng bọc giấy bạc với sả, hành tây, tỏi, ít dầu ăn; nướng lò. Giữ ẩm tốt, fat từ dầu ướp. Phần ăn được.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('27d3f72e-774b-45c5-b963-cb5824b527bf', 'Cá sốt cà chua', 'CHINH', 'CA', 170, 14, 9, 6, 140, 'đĩa nhỏ', 'Cá rô phi rán sơ rồi sốt cà chua + hành tây + ít đường. base_serving gồm cả nước sốt nên kcal/100g pha loãng so với cá rán đơn thuần.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('16e9e839-2760-480c-abf7-7cf94cf36c96', 'Cá xào chua ngọt', 'CHINH', 'CA', 220, 14, 10, 16, 140, 'đĩa nhỏ', 'Cá basa phi lê tẩm bột chiên giòn, xào với dứa, ớt chuông, hành tây, sốt chua ngọt (đường + giấm + tương cà). Carb cao do đường + dứa + bột.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('dd8766a4-332c-4fe5-bc83-59dff9907091', 'Chả cá thì là', 'CHINH', 'CA', 220, 16, 14, 6, 120, 'đĩa nhỏ', 'Cá thác lác xay + mỡ heo + thì là + bột năng + trứng làm chất kết dính, nặn miếng rồi chiên. Macro khác cá nguyên: protein hơi thấp, fat/carb cao hơn do mỡ heo và bột.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('61b783e8-5d0c-4869-aead-e9f49d4f27a6', 'Cá lóc om dưa', 'CHINH', 'CA', 105, 12, 5, 3, 180, 'đĩa nhỏ', 'Cá lóc om với dưa cải chua, cà chua, thì là. Có nước om. base_serving lớn vì gồm cá + dưa + nước nên kcal/100g thấp.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e8e5e26f-a878-4e35-bae4-dccf440dad4c', 'Tôm rang', 'CHINH', 'HAI_SAN', 150, 18, 6, 6, 100, 'đĩa nhỏ', 'Tôm sú để cả vỏ rang khô với dầu, đường nâu, nước mắm cho đến khi sốt sệt áo đều. Phiên bản nguyên bản không thêm thịt ba chỉ. Vỏ tôm ăn được.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d527dd04-6d5a-434e-a7ac-ff027bbb0178', 'Tôm kho tàu', 'CHINH', 'HAI_SAN', 160, 16, 7, 8, 100, 'đĩa nhỏ', 'Tôm kho với nước dừa tươi, nước hàng và đường theo kiểu Nam Bộ. Carb cao hơn tôm rang do đường nước hàng và đường tự nhiên trong nước dừa.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('7d1308ca-5583-4c3b-9658-65d1988eb498', 'Tôm rim nước mắm', 'CHINH', 'HAI_SAN', 140, 18, 5, 5, 100, 'đĩa nhỏ', 'Tôm thẻ rim với nước mắm và đường, sốt cô lại sệt. Vỏ tôm mềm sau khi rim nên ăn được cả vỏ.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('c7b17c20-fa7c-40af-8a8d-93d6d6ef4c26', 'Tôm hấp', 'CHINH', 'HAI_SAN', 100, 20, 1.5, 0.5, 120, 'đĩa nhỏ', 'Tôm sú hấp với sả/lá chanh hoặc hấp bia, gần như không thêm dầu. kcal/macro tính cho phần thịt ăn được, không tính vỏ (yield ~70%, 1 đĩa 170g cả vỏ ≈ 120g thịt).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('df16ee43-4166-4974-b020-be96d5809ad0', 'Tôm chiên xù', 'CHINH', 'HAI_SAN', 240, 16, 12, 15, 120, 'đĩa nhỏ', 'Tôm tẩm bột chiên xù chiên ngập dầu. Carb cao do bột chiên (~15g/100g) và fat cao do hút dầu khi chiên. Tham chiếu USDA breaded fried shrimp.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('935ee8c5-757f-45eb-a773-b2556504ca0f', 'Mực xào dứa', 'CHINH', 'HAI_SAN', 120, 13, 4, 8, 130, 'đĩa nhỏ', 'Mực ống xào với dứa, hành tây, cần tây. Carb cao hơn mực xào thường do dứa chiếm ~25-30% khối lượng (carb tự nhiên từ dứa ~10g/100g).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('732b65a8-013d-4843-a654-eeb0cdd89322', 'Mực xào sa tế', 'CHINH', 'HAI_SAN', 145, 14, 8, 4, 120, 'đĩa nhỏ', 'Mực ống xào nhanh lửa to với sa tế, hành tây. Fat cao hơn mực xào thường do dầu sa tế. Cay.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('1c5aa6e3-51aa-47e7-b98b-7132d6d0c30f', 'Mực chiên giòn', 'CHINH', 'HAI_SAN', 215, 13, 11, 15, 120, 'đĩa nhỏ', 'Mực ống cắt khoanh tẩm bột chiên giòn, chiên ngập dầu. Carb cao do bột chiên, khác hẳn mực xào (chỉ áo nhẹ tinh bột năng).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('3886a6d8-86ec-4ad7-9a7c-44243c6ab232', 'Ngao hấp sả', 'CHINH', 'HAI_SAN', 110, 18, 2, 4, 80, 'đĩa nhỏ', 'Ngao hấp với sả, lá chanh, ớt. kcal/macro tính cho phần thịt ăn được, không tính vỏ (yield ~25-30%, 1 đĩa 300g cả vỏ ≈ 80g thịt). Tham chiếu USDA cooked clams.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('81668f66-7cb5-40ac-9fc0-43cf829524ac', 'Nghêu xào tỏi ớt', 'CHINH', 'HAI_SAN', 140, 17, 6, 4, 80, 'đĩa nhỏ', 'Nghêu xào nhanh lửa to với tỏi, ớt, rau răm. Có thêm dầu xào nên kcal cao hơn ngao hấp. kcal/macro tính cho phần thịt ăn được, không tính vỏ (1 đĩa 280g cả vỏ ≈ 80g thịt).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('808b90f3-41e8-4e23-a92b-2b6d081db402', 'Cua rang me', 'CHINH', 'HAI_SAN', 165, 15, 7, 10, 80, 'đĩa nhỏ', 'Cua biển sốt me chua ngọt, sốt sệt áo đều. Carb cao do nước cốt me + đường trong sốt (~10g/100g món). kcal/macro tính cho phần thịt+gạch ăn được, không tính vỏ (yield ~25-30%, 1 con cua 250g ≈ 65-80g thịt).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('18f8295e-5cc5-4d4c-97ca-14e3c5b1c705', 'Bạch tuộc nướng sa tế', 'CHINH', 'HAI_SAN', 160, 20, 6, 4, 100, 'phần', 'Bạch tuộc cắt miếng ướp sa tế nướng than. Yield cao (~85-90%) nên base_serving tính gần như cả khối lượng món sau nướng. Cay.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('ec43f33a-2372-4b57-8b9a-a10306f76687', 'Trứng chiên', 'CHINH', 'TRUNG', 200, 13, 16, 1, 100, 'đĩa nhỏ', 'Trứng đánh tan rán phẳng với hành lá; món cơ bản, dầu vừa phải.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d5d58337-e436-4bcf-8b09-f9a5de57c328', 'Trứng ốp la', 'CHINH', 'TRUNG', 180, 13, 14, 0.5, 100, 'phần', 'Trứng rán nguyên quả lòng đào hoặc chín, ăn kèm xì dầu; ít dầu hơn trứng chiên đánh tan.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('792e0882-526b-4885-9b72-c5ba493b1f83', 'Trứng chiên thịt băm', 'CHINH', 'TRUNG', 220, 15, 17, 1, 130, 'đĩa nhỏ', 'Trứng đánh tan trộn thịt heo băm và hành lá rồi rán phẳng; carb thấp.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
