('b0df1ef6-3829-4d26-b4cb-a0638638e92a', 'Trứng kho tiêu', 'CHINH', 'TRUNG', 210, 14, 14, 5, 100, 'phần', 'Trứng luộc kho khô với mắm và TIÊU; không có thịt; tiêu nhiều là đặc trưng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
