('3146a2a6-d64e-4bec-9b1d-ebde9a09653d', 'Bánh mì sandwich', 'TINH_BOT', 'TINH_BOT_MI', 270, 8.5, 3.2, 48, 60, 'lát', 'Bánh mì gối/sandwich loaf, tương đương white bread USDA (~270 kcal/100g). base_serving = 2 lát mỏng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('17214b7e-26b6-4685-8d75-fe90f86900e1', 'Mì tôm (đã luộc)', 'TINH_BOT', 'TINH_BOT_MI', 155, 3.4, 5.5, 21, 220, 'phần', 'Mì tôm đã luộc từ 1 gói 80g khô (tăng ~2.75x do hút nước). Vẫn còn dầu chiên từ khâu sản xuất nên F cao hơn mì thường. KHÔNG bao gồm gói gia vị.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e402efee-6561-46a0-a472-bf1119786381', 'Mì trứng tươi (đã luộc)', 'TINH_BOT', 'TINH_BOT_MI', 140, 5, 2, 25, 200, 'phần', 'Sợi mì bột mì + trứng, đã luộc và ráo. Tương đương USDA egg noodles cooked (~138 kcal). P cao hơn mì thường do có trứng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e32c4f25-f3d5-4eed-9f31-fd8197af71c8', 'Mì Ý (đã luộc)', 'TINH_BOT', 'TINH_BOT_MI', 158, 5.8, 0.9, 31, 180, 'phần', 'Spaghetti đã luộc từ 90g khô. Theo USDA pasta cooked enriched without salt (~158 kcal). Fat rất thấp do không có dầu chiên.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('590aa464-d7da-4f4d-aff7-2ab1e918ecad', 'Mì udon (đã luộc)', 'TINH_BOT', 'TINH_BOT_MI', 130, 3, 0.3, 27.5, 200, 'phần', 'Mì udon Nhật đã luộc, sợi dày bột mì thuần. USDA udon cooked ~127 kcal; FatSecret VN ~140 kcal, lệch ~10%. Lấy giá trị giữa nghiêng USDA.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8242bdd2-7b37-4a8e-980b-dc17e0e7f1ce', 'Phở bò', 'COMBO', 'COMBO', 75, 5, 2.5, 9, 500, 'tô', 'Bánh phở + thịt bò thăn/tái + nước dùng xương bò trong. Kiểu Bắc.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8de44f4f-7996-4311-83ff-4c24242476cd', 'Phở gà', 'COMBO', 'COMBO', 70, 5.5, 1.5, 9, 500, 'tô', 'Bánh phở + ức gà xé + nước dùng gà trong; fat thấp hơn phở bò do dùng ức gà.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('446d6e3e-2fe4-495e-8858-bf031cdaa020', 'Bún bò Huế', 'COMBO', 'COMBO', 90, 5.5, 4, 8.5, 500, 'tô', 'Bún sợi to + thịt bò bắp + giò heo + nước dùng sả/mắm ruốc/dầu điều. Kiểu Trung, đậm và cay.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('6f00bd11-02a0-473c-810f-dd62aec9c20b', 'Bún chả', 'COMBO', 'COMBO', 160, 7, 6, 18, 350, 'phần', 'Bún tươi + chả nướng (viên + miếng) + chén nước mắm chua ngọt riêng + rau sống. Kiểu Bắc. Không có nước dùng đổ vào bún nên kcal/100g cao.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d0f9c192-d30d-480f-b21c-b307418bb76a', 'Bún riêu cua', 'COMBO', 'COMBO', 80, 5, 3, 9, 500, 'tô', 'Bún + riêu cua đồng + cà chua + đậu phụ rán + nước dùng cua chua nhẹ.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('302ab1f0-4fc7-4bb0-a3f3-586cd561c517', 'Bún ốc', 'COMBO', 'COMBO', 70, 4.5, 1.5, 10, 500, 'tô', 'Bún + ốc nhồi + nước dùng giấm bỗng/me chua thanh. Không có đậu rán nên kcal thấp nhất nhóm bún nước.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('9f72149c-4edc-4c5d-a9bc-eed4e91106cb', 'Bún đậu mắm tôm', 'COMBO', 'COMBO', 200, 9, 8, 21, 400, 'phần', 'Bún + đậu phụ rán + chả cốm + thịt ba chỉ luộc + mắm tôm pha + rau sống. Kiểu Bắc, kcal cao nhất nhóm bún do nhiều topping rán.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('3d210f99-e30e-4ae0-bfc7-9350d8611403', 'Cơm tấm sườn', 'COMBO', 'COMBO', 180, 7.5, 6.5, 22, 350, 'đĩa', 'Cơm tấm + sườn nướng + bì heo trộn thính + chả trứng + mỡ hành + đồ chua + nước mắm chua ngọt. Kiểu Nam.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('3f498061-8cae-46b0-b978-8cfcbf5e7772', 'Cơm gà Hội An', 'COMBO', 'COMBO', 165, 7, 5, 22, 350, 'đĩa', 'Cơm vàng (nấu bằng nước luộc gà + nghệ) + thịt gà xé + rau răm + đu đủ bào + nước mắm gừng. Kiểu Trung.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d2b8824d-19e7-4f83-bc3c-2a3266eac307', 'Bánh mì thịt', 'COMBO', 'COMBO', 260, 10, 9, 32, 200, 'ổ', 'Bánh mì baguette + pate gan + thịt nguội (chả lụa/jambon) + chả + dưa chuột + đồ chua + rau mùi + tương ớt. Water content thấp nên kcal/100g cao.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('feda9014-8ff3-450f-932d-82ae32304eb2', 'Mì Quảng', 'COMBO', 'COMBO', 130, 6.5, 4.5, 16, 400, 'tô', 'Sợi mì gạo nhuộm nghệ vàng + tôm + thịt heo ba chỉ + nước dùng đậm (1/4 phở) + đậu phộng rang giã + bánh tráng nướng. Đặc sản Quảng Nam.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('59e831f6-f067-4e95-9ed1-9dc24fc9d0fd', 'Hủ tiếu Nam Vang', 'COMBO', 'COMBO', 80, 4.5, 2, 11, 500, 'tô', 'Sợi hủ tiếu bột gạo + thịt heo nạc + tôm + gan + trứng cút + nước xương heo trong. Gốc Phnom Penh, phổ biến miền Nam.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8f6e7e3a-aa57-4285-9cd4-fb0f02558e30', 'Bánh canh giò heo', 'COMBO', 'COMBO', 110, 5.5, 4.5, 12.5, 480, 'tô', 'Sợi bánh canh dày (bột gạo pha bột sắn) + giò heo hầm + nước dùng đậm. Phổ biến Trung-Nam, đặc biệt Huế và Sài Gòn.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('68b3159a-bcd3-4f0c-8380-180321645b4f', 'Xôi xéo', 'COMBO', 'COMBO', 250, 7, 8, 36, 250, 'đĩa', 'Xôi nếp + đậu xanh đãi vỏ nghiền nhuyễn + hành phi (nhiều dầu) + ruốc thịt hoặc giò lụa. Đặc sản ăn sáng Hà Nội.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('6a91a0d7-1a69-46e8-82ce-b4cf12d62b81', 'Cháo gà', 'COMBO', 'COMBO', 75, 5, 1.5, 10, 400, 'tô', 'Cháo gạo tẻ loãng + thịt gà xé + hành lá + gừng thái sợi + tiêu. Bữa sáng nhẹ phổ biến cả ba miền.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('5b8d5077-3721-433e-989d-6059b94efca6', 'Bún thang', 'COMBO', 'COMBO', 85, 6, 2, 11, 500, 'tô', 'Bún tươi + giò lụa thái sợi + trứng tráng mỏng cắt sợi + gà ức xé + ruốc tôm + nước dùng rất trong từ xương gà và tôm khô. Đặc sản Hà Nội.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('4cd8c58e-3278-4777-92f2-a2590076fcbc', 'Bún mọc', 'COMBO', 'COMBO', 90, 5.5, 3, 11, 500, 'tô', 'Bún tươi + mọc viên (giò sống trộn nấm hương, mộc nhĩ băm, viên tròn) + sườn non + nước dùng trong xương heo. Đặc trưng miền Bắc.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('c8581cb5-dba2-48a7-bd21-086e457cdc13', 'Bún cá', 'COMBO', 'COMBO', 95, 6, 3.5, 10, 500, 'tô', 'Bún tươi + cá rán (cá rô/cá quả) + nước dùng cá + thì là + rau cần. Phổ biến Hà Nội và Hải Phòng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('a879d7bd-13ca-40fa-9656-8924f8d04023', 'Phở xào bò', 'COMBO', 'COMBO', 180, 8.5, 6, 22, 340, 'đĩa', 'Bánh phở xào với thịt bò thăn thái mỏng + rau cải ngọt + hành tây + tỏi + dầu ăn. KHÔNG có nước dùng. Phổ biến hàng quán cả ba miền.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('186a0d15-182e-41e2-bcf4-a9573bc2629a', 'Hủ tiếu mì', 'COMBO', 'COMBO', 95, 5.5, 2.5, 12, 500, 'tô', 'Trộn 2 loại tinh bột (sợi hủ tiếu bột gạo + mì trứng tươi) + thịt heo nạc + tôm + gan heo + nước dùng xương. Đặc trưng người Hoa miền Nam.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('b3690131-fd9c-4f67-9bf5-4b556963e071', 'Mì xào giòn hải sản', 'COMBO', 'COMBO', 210, 9.5, 9.5, 22, 350, 'đĩa', 'Mì trứng chiên ngập dầu thành ổ giòn + sốt sệt hải sản (tôm/mực) rưới lên + rau cải. Kỹ thuật chiên giòn → fat cao.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e8c653d6-837d-47de-a514-33f3476a64d6', 'Mì xào bò', 'COMBO', 'COMBO', 180, 8.5, 6.5, 22, 330, 'đĩa', 'Mì trứng tươi xào lửa lớn với thịt bò thái mỏng + rau cải + hành tây. Kỹ thuật xào (không chiên ngập dầu).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d36efdfc-f4e8-4f95-85e1-e3c95b09c7e8', 'Cơm rang dưa bò', 'COMBO', 'COMBO', 165, 6.5, 5.5, 23, 320, 'đĩa', 'Cơm nguội rang với dưa cải chua + thịt bò xé sợi + trứng + hành lá. Vị chua nhẹ đặc trưng miền Bắc.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('87f550a9-50d5-4f3f-b615-44e84a0fc7e7', 'Cơm rang trứng', 'COMBO', 'COMBO', 165, 5.5, 6, 22, 280, 'đĩa', 'Cơm nguội rang với trứng + hành lá + nước mắm/hạt nêm. Phiên bản cơm rang cơ bản nhất.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('9b2d70fb-a890-4524-8573-6f8516f3b011', 'Cơm rang thập cẩm', 'COMBO', 'COMBO', 175, 7, 7, 22, 320, 'đĩa', 'Cơm rang với xúc xích/giăm bông + trứng + đậu Hà Lan + cà rốt + hành lá. Topping đa dạng → kcal cao hơn cơm rang trứng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('1a6c09b5-ff4d-494b-82ea-da359420d336', 'Cơm gà xối mỡ', 'COMBO', 'COMBO', 210, 10, 9, 22, 370, 'đĩa', 'Cơm trắng + đùi gà chiên giòn da + mỡ nóng xối lên + nước mắm gừng + dưa chua. Kỹ thuật xối mỡ làm fat tăng đáng kể.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8d9a94f4-a15c-4515-a585-774060e1a460', 'Cơm sườn nướng', 'COMBO', 'COMBO', 195, 9, 7.5, 22, 370, 'đĩa', 'Cơm trắng + sườn cốt lết heo ướp nướng than + dưa chua + mỡ hành. Có canh nhỏ kèm (không tính vào base_serving).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('390a75d5-5751-42eb-a45e-fd4853ebedbf', 'Cơm bò lúc lắc', 'COMBO', 'COMBO', 185, 9, 7, 21, 380, 'đĩa', 'Cơm trắng + bò thăn cắt khối vuông xào lửa lớn lúc lắc trên chảo + ớt chuông/hành tây + sốt tiêu + trứng ốp la phủ trên.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e4a1860b-35f0-4653-8042-e525d4fcc32b', 'Bánh cuốn', 'COMBO', 'COMBO', 135, 5.5, 3.5, 20, 350, 'phần', 'Bánh cuốn bột gạo hấp cuốn nhân thịt heo băm mộc nhĩ + chả lụa/chả quế + nước mắm pha + hành phi + rau thơm. Kỹ thuật hấp → ít dầu nhất batch.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('05ef35cd-5c7e-4fa8-9875-6b6312f15b77', 'Xôi gà', 'COMBO', 'COMBO', 240, 9, 7, 35, 280, 'phần', 'Xôi nếp đồ + gà xé hoặc lườn gà chiên + hành phi (nhiều dầu) + ruốc thịt. Nếp dày + hành phi → kcal/100g cao nhất batch.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('58675634-f0ee-4552-ae96-afd89e5dd592', 'Chuối tiêu', 'BUA_PHU', 'BUA_PHU', 89, 1.1, 0.3, 22.8, 85, 'quả', 'Chuối tiêu chín (phần thịt, đã bỏ vỏ). 1 quả ~120g cả vỏ = ~85g thịt ≈ 76 kcal. Trái cây bữa phụ phổ biến, giàu K.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('980dc50a-d431-4aad-9d4e-e3c75c924baa', 'Táo', 'BUA_PHU', 'BUA_PHU', 52, 0.3, 0.2, 13.8, 150, 'quả', 'Táo Mỹ/Pháp ăn cả vỏ. 1 quả vừa ~150g ≈ 78 kcal. GI thấp, giàu chất xơ pectin.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('e245648c-3da6-404a-9109-fbf31ab5051b', 'Cam', 'BUA_PHU', 'BUA_PHU', 47, 0.9, 0.1, 11.8, 130, 'phần', 'Cam tươi múi (đã bỏ vỏ và hột). ~2 quả nhỏ = 130g múi ≈ 61 kcal. Giàu vitamin C.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('efa5e8c1-3503-44e9-b9c1-887ce27cb4dd', 'Ổi', 'BUA_PHU', 'BUA_PHU', 68, 2.6, 0.95, 14.3, 120, 'quả', 'Ổi tươi ăn cả vỏ (có thể bỏ hột). 1 quả to ~120g ≈ 82 kcal. Vitamin C rất cao (~200mg/100g).', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('7166f1c2-a3c1-4eba-92ad-c07da4970770', 'Đu đủ chín', 'BUA_PHU', 'BUA_PHU', 43, 0.5, 0.3, 10.8, 150, 'phần', 'Đu đủ chín thái miếng (đã gọt vỏ, bỏ hột). 1 phần 150g ≈ 65 kcal. Giàu beta-carotene.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('75bd8f3b-08be-49f2-85b3-ad5ca31becba', 'Sữa chua không đường', 'BUA_PHU', 'BUA_PHU', 60, 4, 3, 5, 100, 'hộp', 'Sữa chua plain không đường (Vinamilk/TH True Yogurt). 1 hộp 100g ≈ 60 kcal. Probiotic tốt cho tiêu hóa.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('902164fe-173f-4b52-ae3c-ad934fdc90b9', 'Sữa tươi không đường', 'BUA_PHU', 'BUA_PHU', 60, 3.3, 3.4, 4.6, 200, 'hộp', 'Sữa tươi tiệt trùng không đường (whole milk). 1 hộp UHT 200ml ≈ 120 kcal. Quy ước 1ml = 1g.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('8475368d-ac0a-43e4-82c4-cf465a793c1c', 'Sữa đậu nành không đường', 'BUA_PHU', 'BUA_PHU', 35, 3, 1.8, 1.5, 200, 'ly', 'Sữa đậu nành nguyên chất không đường (Vinasoy/tự nấu). 1 ly/chai 200ml ≈ 70 kcal. Quy ước 1ml = 1g.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('d22508cf-d631-4e81-bca0-9e5db7156129', 'Hạt điều rang', 'BUA_PHU', 'BUA_PHU', 574, 15.3, 46.4, 32.7, 30, 'phần', 'Hạt điều rang khô không muối. 1 phần 30g (~20 hạt) ≈ 172 kcal. KCAL CỰC CAO, không ăn 100g/lần.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('553d4dc4-d10b-44dd-8221-9e82d8a1dae0', 'Hạt óc chó', 'BUA_PHU', 'BUA_PHU', 654, 15.2, 65.2, 13.7, 25, 'phần', 'Hạt óc chó nguyên bóc. 1 phần 25g (~5-6 hạt) ≈ 164 kcal. Giàu omega-3 ALA. KCAL CỰC CAO.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('fae9b077-f74e-4419-a1ac-277a20f25259', 'Đậu phộng rang', 'BUA_PHU', 'BUA_PHU', 580, 24, 49, 21, 30, 'vốc', 'Đậu phộng/lạc rang khô không muối. 1 vốc 30g ≈ 174 kcal. Giàu protein và chất béo không bão hòa.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('cf69ac0f-7060-4c22-a13e-f5472eb09c1a', 'Bánh quy lạt', 'BUA_PHU', 'BUA_PHU', 440, 7, 16, 68, 30, 'cái', 'Bánh quy lạt ít đường (AFC/Lipo). ~3 cái = 30g ≈ 132 kcal. Phù hợp ăn vặt nhẹ với trà.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('c1772d4f-d6e6-4007-b907-994e7717c72d', 'Khoai lang luộc', 'BUA_PHU', 'BUA_PHU', 76, 1.4, 0.1, 17.7, 150, 'củ', 'Khoai lang luộc (đã gọt vỏ). 1 củ vừa 150g ≈ 114 kcal. GI thấp hơn cơm trắng, phù hợp ăn kiêng.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM'),
('dcaab4ba-5145-45b2-9e8c-6199b67671e5', 'Ngô luộc', 'BUA_PHU', 'BUA_PHU', 96, 3.3, 1.5, 19.5, 150, 'bắp', 'Ngô ngọt luộc (phần hạt, đã bỏ lõi và vỏ). 1 bắp ~250g cả lõi = 150g hạt ≈ 144 kcal.', TRUE, NOW(), NOW(), 'SYSTEM', 'SYSTEM');


